import{_ as p,v as b,C as v,o as n,c as o,a8 as l,j as a,a as t,e as c,E as u,p as f}from"./chunks/framework.Ch5T2Gh4.js";const g={key:0},m={key:1},y=JSON.parse('{"title":"Titiler Integration","description":"","frontmatter":{"title":"Titiler Integration","layout":"page"},"headers":[],"relativePath":"software-services/titiler/index.md","filePath":"software-services/titiler/index.md"}'),h={name:"software-services/titiler/index.md"},k=Object.assign(h,{setup(x){const i=f(!1),s=f(!0);return b(async()=>{try{const r=await fetch("https://api.explorer.eopf.copernicus.eu/raster/_mgmt/ping");i.value=r.ok}catch{i.value=!1}finally{s.value=!1}}),(r,e)=>{const d=v("FeaturesGallery");return n(),o("div",null,[e[2]||(e[2]=l('<h2 id="titiler-integration" tabindex="-1" data-v-cf248ebf>Titiler Integration <img src="https://user-images.githubusercontent.com/10407788/172718020-c2378b7e-a0d4-406e-924c-8ffe54e61596.png" alt="Titiler Logo" style="height:100px;vertical-align:middle;margin-left:0.5rem;float:right;" data-v-cf248ebf> <a class="header-anchor link" href="#titiler-integration" aria-label="Permalink to &quot;Titiler Integration &lt;img src=&quot;https://user-images.githubusercontent.com/10407788/172718020-c2378b7e-a0d4-406e-924c-8ffe54e61596.png&quot; alt=&quot;Titiler Logo&quot; style=&quot;height:100px;vertical-align:middle;margin-left:0.5rem;float:right;&quot; /&gt;&quot;" data-v-cf248ebf>​</a></h2><h3 id="overview" tabindex="-1" data-v-cf248ebf>Overview <a class="header-anchor link" href="#overview" aria-label="Permalink to &quot;Overview&quot;" data-v-cf248ebf>​</a></h3><p data-v-cf248ebf>This guide demonstrates how to use Titiler-EOPF, a specialized tile server that provides on-the-fly visualization of EOPF&#39;s Zarr-formatted satellite data. Unlike client-side processing, Titiler handles complex calculations server-side and delivers optimized tiles for web mapping applications.</p>',3)),s.value?(n(),o("div",g,[...e[0]||(e[0]=[a("div",{class:"tip custom-block"},[a("p",{class:"custom-block-title"},[t("💡 "),a("strong",null,[t("Checking "),a("a",{href:"https://api.explorer.eopf.copernicus.eu/raster",class:"link vp-external-link-icon",target:"_blank",rel:"noreferrer"},"API"),t(" Status")]),t(":Verifying Titiler service availability...")])],-1)])])):c("",!0),i.value?c("",!0):(n(),o("div",m,[...e[1]||(e[1]=[a("div",{class:"warning custom-block"},[a("p",{class:"custom-block-title"},[t("⚠️ "),a("strong",null,[a("a",{href:"https://api.explorer.eopf.copernicus.eu/raster",class:"link vp-external-link-icon",target:"_blank",rel:"noreferrer"},"API"),t(" Unavailable")]),t(":: The Titiler service appears to be temporarily unavailable. Some examples may not work as expected.")])],-1)])])),e[3]||(e[3]=l('<br data-v-cf248ebf><div class="info custom-block" data-v-cf248ebf><p class="custom-block-title" data-v-cf248ebf><strong data-v-cf248ebf><i class="mdi mdi-target" data-v-cf248ebf></i> What You&#39;ll Learn</strong></p><p data-v-cf248ebf>This integration guide covers server-side tile generation using EOPF&#39;s Titiler service, enabling you to build responsive web applications without handling complex data processing in the browser. Each example demonstrates practical implementation patterns for real-world applications.</p><p data-v-cf248ebf><strong data-v-cf248ebf>Sample Data</strong> used here are available in <a href="https://api.explorer.eopf.copernicus.eu/browser/external/api.explorer.eopf.copernicus.eu/stac/collections/sentinel-2-l2a" class="link vp-external-link-icon" target="_blank" rel="noreferrer" data-v-cf248ebf>the Sentinel-2 L2A collection in STAC Browser</a></p></div><h3 id="quick-start" tabindex="-1" data-v-cf248ebf>Quick Start <a class="header-anchor link" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;" data-v-cf248ebf>​</a></h3><br data-v-cf248ebf><div class="info custom-block" data-v-cf248ebf><p class="custom-block-title" data-v-cf248ebf><strong data-v-cf248ebf><i class="mdi mdi-rocket-launch" data-v-cf248ebf></i> Get Started in 5 Minutes</strong></p><p data-v-cf248ebf>Ready to dive in? Start with the <a href="./rgb" class="link" data-v-cf248ebf>RGB Visualization example</a> to see Titiler serving EOPF tiles in a web map, then explore NDVI calculations and spatial cropping techniques</p></div><br data-v-cf248ebf><div class="warning custom-block" data-v-cf248ebf><p class="custom-block-title" data-v-cf248ebf>⚠️ <strong data-v-cf248ebf>Early Implementation</strong></p><p data-v-cf248ebf>This Titiler integration represents an early implementation of EOPF data services. Data availability, API stability, and library alignment will evolve over time as the platform matures.</p></div><h3 id="api-documentation" tabindex="-1" data-v-cf248ebf>API Documentation <a class="header-anchor link" href="#api-documentation" aria-label="Permalink to &quot;API Documentation&quot;" data-v-cf248ebf>​</a></h3><div class="grid" data-v-cf248ebf><div class="s12 m6" data-v-cf248ebf><div class="info custom-block" data-v-cf248ebf><p class="custom-block-title" data-v-cf248ebf>Interactive API Docs</p><p data-v-cf248ebf><a href="https://api.explorer.eopf.copernicus.eu/raster/api.html" class="link vp-external-link-icon" target="_blank" rel="noreferrer" data-v-cf248ebf>Swagger UI Documentation</a></p><p data-v-cf248ebf>Complete API reference with interactive examples and endpoint testing.</p></div></div><div class="s12 m6" data-v-cf248ebf><div class="info custom-block" data-v-cf248ebf><p class="custom-block-title" data-v-cf248ebf>Base URL</p><p data-v-cf248ebf><a href="https://api.explorer.eopf.copernicus.eu/raster/" class="link vp-external-link-icon" target="_blank" rel="noreferrer" data-v-cf248ebf>https://api.explorer.eopf.copernicus.eu/raster/</a></p><p data-v-cf248ebf>All tile endpoints use this base URL for production integration.</p><br data-v-cf248ebf></div></div></div><h3 id="key-concepts" tabindex="-1" data-v-cf248ebf>Key Concepts <a class="header-anchor link" href="#key-concepts" aria-label="Permalink to &quot;Key Concepts&quot;" data-v-cf248ebf>​</a></h3><p data-v-cf248ebf><strong data-v-cf248ebf>Server-Side Processing</strong></p><p data-v-cf248ebf>Titiler-EOPF performs all data processing server-side, including:</p><ul data-v-cf248ebf><li data-v-cf248ebf><strong data-v-cf248ebf>On-the-fly tile generation</strong> from Zarr datasets</li><li data-v-cf248ebf><strong data-v-cf248ebf>Mathematical expressions</strong> for band combinations and indices</li><li data-v-cf248ebf><strong data-v-cf248ebf>Color enhancement</strong> with gamma correction and contrast adjustment</li><li data-v-cf248ebf><strong data-v-cf248ebf>Spatial operations</strong> like cropping and reprojection</li></ul><p data-v-cf248ebf><strong data-v-cf248ebf>Variable Naming Convention</strong></p><p data-v-cf248ebf>Band references use the format:</p><div class="language- vp-adaptive-theme" data-v-cf248ebf><button title="Copy Code" class="copy" data-v-cf248ebf></button><span class="lang" data-v-cf248ebf></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-cf248ebf><code data-v-cf248ebf><span class="line" data-v-cf248ebf><span data-v-cf248ebf>/measurements/reflectance:b04</span></span></code></pre></div><ul data-v-cf248ebf><li data-v-cf248ebf><code data-v-cf248ebf>measurements/reflectance</code> - Multiscales group path in Zarr structure</li><li data-v-cf248ebf><code data-v-cf248ebf>b04</code> - Specific band identifier (Red band)</li></ul><p data-v-cf248ebf><strong data-v-cf248ebf>URL Structure</strong></p><p data-v-cf248ebf>Tile endpoints follow this pattern:</p><div class="language- vp-adaptive-theme" data-v-cf248ebf><button title="Copy Code" class="copy" data-v-cf248ebf></button><span class="lang" data-v-cf248ebf></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-cf248ebf><code data-v-cf248ebf><span class="line" data-v-cf248ebf><span data-v-cf248ebf>/raster/collections/{collection}/items/{item}/tiles/WebMercatorQuad/{z}/{x}/{y}.png</span></span></code></pre></div><h3 id="deployment-options" tabindex="-1" data-v-cf248ebf>Deployment Options <a class="header-anchor link" href="#deployment-options" aria-label="Permalink to &quot;Deployment Options&quot;" data-v-cf248ebf>​</a></h3><p data-v-cf248ebf><strong data-v-cf248ebf>1. <a href="https://api.explorer.eopf.copernicus.eu/raster/" class="link vp-external-link-icon" target="_blank" rel="noreferrer" data-v-cf248ebf>EOPF Explorer TiTiler</a> (Recommended)</strong></p><ul data-v-cf248ebf><li data-v-cf248ebf><strong data-v-cf248ebf>Pre-configured</strong> with STAC catalog integration</li><li data-v-cf248ebf><strong data-v-cf248ebf>Production-ready</strong> endpoints with optimized performance</li><li data-v-cf248ebf><strong data-v-cf248ebf>No authentication</strong> required for public data</li><li data-v-cf248ebf><strong data-v-cf248ebf>Automatic updates</strong> with latest EOPF data</li></ul><p data-v-cf248ebf><strong data-v-cf248ebf>2. Self-Hosted Instance</strong></p><p data-v-cf248ebf>For custom deployments, see the <a href="https://github.com/EOPF-Explorer/titiler-eopf" class="link vp-external-link-icon" target="_blank" rel="noreferrer" data-v-cf248ebf>titiler-eopf repository</a> for:</p><ul data-v-cf248ebf><li data-v-cf248ebf>Docker Compose setup instructions</li><li data-v-cf248ebf>Kubernetes/Helm deployment guides</li><li data-v-cf248ebf>Environment configuration examples</li><li data-v-cf248ebf>Custom data source integration</li></ul><h3 id="next-steps" tabindex="-1" data-v-cf248ebf>Next Steps <a class="header-anchor link" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;" data-v-cf248ebf>​</a></h3><ol data-v-cf248ebf><li data-v-cf248ebf><strong data-v-cf248ebf>Start with Examples</strong>: Work through each <a href="#integration-examples" class="link" data-v-cf248ebf>example</a> to understand the capabilities</li><li data-v-cf248ebf><strong data-v-cf248ebf>Explore API Documentation</strong>: Use the <a href="https://api.explorer.eopf.copernicus.eu/raster/api.html" class="link vp-external-link-icon" target="_blank" rel="noreferrer" data-v-cf248ebf>interactive Swagger UI</a> to test endpoints</li><li data-v-cf248ebf><strong data-v-cf248ebf>Browse EOPF Data</strong>: Find datasets in the <a href="https://api.explorer.eopf.copernicus.eu/browser" class="link vp-external-link-icon" target="_blank" rel="noreferrer" data-v-cf248ebf>STAC Browser</a></li><li data-v-cf248ebf><strong data-v-cf248ebf>Build Applications</strong>: Integrate Titiler tiles into your web mapping projects</li><li data-v-cf248ebf><strong data-v-cf248ebf>Community</strong>: Join <a href="https://discourse.eopf.copernicus.eu/c/eopf-explorer/17" class="link vp-external-link-icon" target="_blank" rel="noreferrer" data-v-cf248ebf>discussions</a> and contribute to the growing EOPF ecosystem</li></ol><p data-v-cf248ebf>For the latest updates and advanced features, follow the <a href="https://github.com/EOPF-Explorer/titiler-eopf" class="link vp-external-link-icon" target="_blank" rel="noreferrer" data-v-cf248ebf>Titiler-EOPF project</a> and <a href="https://github.com/EOPF-Explorer" class="link vp-external-link-icon" target="_blank" rel="noreferrer" data-v-cf248ebf>EOPF Explorer platform</a> on GitHub.</p>',29)),u(d,{background:"transparent",sectionTitle:"Integration Examples",cards:[{title:"1. RGB Band Combinations",content:"Learn to create true color and false color visualizations using Titiler's tile endpoints with OpenLayers or Leaflet.",features:["True color RGB (B04, B03, B02)","False color infrared composites","Color enhancement formulas","Web mapping integration"],link:{text:"View Example",href:"./rgb",target:"_self"}},{title:"2. Vegetation Indices",content:"Calculate vegetation indices server-side using mathematical expressions and visualize with custom color schemes.",features:["Real-time NDVI calculation","Server-side expressions","Custom color mapping","Environmental monitoring"],link:{text:"View Example",href:"./ndvi",target:"_self"}},{title:"3. Spatial Cropping",content:"Extract specific areas from satellite scenes using bounding box and feature-based spatial operations.",features:["Bounding box cropping","Polygon-based extraction","Coordinate system handling","Export capabilities"],link:{text:"View Example",href:"./crop",target:"_self"}}]})])}}}),w=p(k,[["__scopeId","data-v-cf248ebf"]]);export{y as __pageData,w as default};
